sparql_query:
SELECT DISTINCT ?item ?itemLabelRu ?itemLabelEn WHERE {
      ?item wdt:P31/wdt:P279* wd:Q7725634 .
      MINUS { ?item wdt:P31/wdt:P279* wd:Q3331189 . }
      MINUS { ?item wdt:P31/wdt:P279* wd:Q277759 . }
      MINUS { ?item wdt:P31/wdt:P279* wd:Q7725310 . }
      MINUS { ?item wdt:P31/wdt:P279* wd:Q35127 . }
      MINUS { ?item wdt:P31/wdt:P279* wd:Q171 . }
      ?item wdt:P136/wdt:P279* wd:Q24925 .
      ?item wdt:P407 wd:Q150 .
      ?item wdt:P577 ?publicationDate .
      BIND(YEAR(?publicationDate) AS ?publicationYear) .
      FILTER NOT EXISTS { ?item wdt:P577 ?earlierPublicationDate . FILTER(YEAR(?earlierPublicationDate) < ?publicationYear) }
      FILTER(?publicationYear >= 1850) .
      FILTER(?publicationYear <= 1899) .
      ?item rdfs:label ?itemLabelRu FILTER(LANG(?itemLabelRu) = "ru") .
      ?item rdfs:label ?itemLabelEn FILTER(LANG(?itemLabelEn) = "en") .
      FILTER(!REGEX(STR(?itemLabelEn), "[А-Яа-яЁё]")) .
    }
    ORDER BY LCASE(STR(?itemLabelEn))
    LIMIT 101

